1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"sort"
6		"strconv"
7	)
8	
9	// Header is a light-client header at a known height.
10	type Header struct {
11		Chain   string
12		Height  int64
13		Root    string
14		Trusted bool
15	}
16	
17	// Message is one outbound cross-chain message awaiting delivery.
18	type Message struct {
19		ID      string
20		From    string
21		To      string
22		Nonce   uint64
23		Payload string
24		ProofAt int64
25	}
26	
27	// Delivery is the outcome of a relay attempt.
28	type Delivery struct {
29		Message string
30		Status  string
31		Reason  string
32	}
33	
34	// Verify accepts a message only when the header covering it is known and trusted.
35	func Verify(headers map[string]Header, message Message, consumed map[string]bool) Delivery {
36		header, ok := headers[message.From]
37		if !ok {
38			return Delivery{Message: message.ID, Status: "rejected", Reason: "unknown source chain"}
39		}
40		if !header.Trusted || header.Height < message.ProofAt {
41			return Delivery{Message: message.ID, Status: "pending", Reason: "header not yet trusted at proof height"}
42		}
43		key := message.From + ":" + message.To + ":" + strconv.FormatUint(message.Nonce, 10)
44		if consumed[key] {
45			return Delivery{Message: message.ID, Status: "rejected", Reason: "replay: nonce already consumed"}
46		}
47		consumed[key] = true
48		return Delivery{Message: message.ID, Status: "delivered", Reason: "proof verified at height " + strconv.FormatInt(header.Height, 10)}
49	}
50	
51	// Pending lists messages still waiting for a trusted header, stable by id.
52	func Pending(headers map[string]Header, messages []Message) []string {
53		var ids []string
54		for _, message := range messages {
55			header, ok := headers[message.From]
56			if !ok || !header.Trusted || header.Height < message.ProofAt {
57				ids = append(ids, message.ID)
58			}
59		}
60		sort.Strings(ids)
61		return ids
62	}
