821		if s, ok := list[2].(string); !ok || s != "9007199254740993" {
822			t.Fatalf("string-formed number must stay a string, got %T (%v)", list[2], list[2])
823		}
824		if list[3] != true {
825			t.Fatalf("adjacent boolean must keep its type, got %#v", list[3])
826		}
827		if list[4] != nil {
828			t.Fatalf("adjacent null must keep its type, got %#v", list[4])
829		}
830		mustNumber(t, list[5], "3")
831	}
