func TestNormalizeTimestampFormats(t *testing.T) {
	ok := map[string]string{
		"2026-01-02T15:04:05Z":           "2026-01-02T15:04:05Z",
		"2026-01-02T23:04:05+08:00":      "2026-01-02T15:04:05Z",
