		"2026-01-02T15:04:05.100000000Z": "2026-01-02T15:04:05.1Z",
		"2026-01-02T15:04:05.000000000Z": "2026-01-02T15:04:05Z",
		"2026-01-02T15:04:05+00:00":      "2026-01-02T15:04:05Z",
